def facts(expr):
    t = expr.split()
    parent, spouse, male, female = set(), set(), set(), set()
    for i in range(0, len(t) - 2, 2):
        a, op, b = t[i], t[i + 1], t[i + 2]
        if op == "+": parent.add((a, b)); female.add(a)
        elif op == "-": parent.add((a, b)); male.add(a)
        elif op == "$": parent.add((b, a)); male.add(a)
        elif op == "%": female.add(a)
        elif op == "/": spouse |= {(a, b), (b, a)}; female.add(a)
        elif op == "*": spouse |= {(a, b), (b, a)}; male.add(a)
    for (x, y) in list(spouse):          # a spouse shares the children
        for (p, c) in list(parent):
            if p == y: parent.add((x, c))
    return parent, spouse, male, female
def son_wife(expr, p, t):
    parent, spouse, male, female = facts(expr)
    return p in female and any((t, s) in parent and s in male and (s, p) in spouse for s in male)
